mapper.select:
SELECT s.user_id,s.scope_sn,s.scope_type_cd,s.part_id,s.proj_id FROM TB_SY_USER_SCOPE s
WHERE s.scope_type_cd=#{type}
  AND EXISTS (SELECT 1 FROM TB_SY_USER_ROLE ur WHERE ur.user_id=s.user_id AND ur.role_id=#{id})
  AND NOT EXISTS (
    SELECT 1 FROM TB_SY_USER_ROLE ur JOIN TB_SY_ROLE r ON r.role_id=ur.role_id
    WHERE ur.user_id=s.user_id AND r.role_id!=#{id} AND r.use_yn='Y' AND r.data_scope_cd=#{type}
  )
  AND (
    (#{type}='PART' AND EXISTS (SELECT 1 FROM TB_BS_PART p WHERE p.part_id=s.part_id AND p.hq_yn='Y'))
    OR (#{type}='PROJ' AND s.proj_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM TB_SY_USER_ROLE pm WHERE pm.user_id=s.user_id AND pm.role_id='PM'
    ))
  )
ORDER BY s.user_id,s.scope_sn
